def gen(rng):
    def build(n, spine):
        left = [-1] * n
        right = [-1] * n
        slots = [(0, 0), (0, 1)]
        for i in range(1, n):
            if i <= spine:
                j = len(slots) - 1 - rng.randrange(2)
            else:
                j = rng.randrange(len(slots))
            slots[j], slots[-1] = slots[-1], slots[j]
            p, side = slots.pop()
            if side == 0:
                left[p] = i
            else:
                right[p] = i
            slots.append((i, 0))
            slots.append((i, 1))
        return left, right

    def tree_nodes(n, spine, names):
        left, right = build(n, spine)
        return [[names[i], names[left[i]] if left[i] >= 0 else -1, names[right[i]] if right[i] >= 0 else -1] for i in range(n)]

    def make(n, kind, idmax, spine=0):
        if kind == 'forest' and n >= 2:
            names = rng.sample(range(idmax + 1), n)
            a = rng.randint(1, n - 1)
            nodes = tree_nodes(a, spine, names[:a]) + tree_nodes(n - a, spine, names[a:])
        else:
            names = rng.sample(range(idmax + 1), n)
            nodes = tree_nodes(n, spine, names)
        free = [(i, s) for i in range(len(nodes)) for s in (1, 2) if nodes[i][s] == -1]
        if kind == 'extra' and free:
            i, s = rng.choice(free)
            nodes[i][s] = names[rng.randrange(n)]
        elif kind == 'missing' and free:
            i, s = rng.choice(free)
            nodes[i][s] = idmax + 1 + rng.randint(0, 5)
        elif kind == 'drop' and n >= 2:
            nodes.pop(rng.randrange(len(nodes)))
        elif kind == 'cycle' and free:
            i, s = rng.choice(free)
            nodes[i][s] = names[0]
        elif kind == 'dup':
            one = [nd for nd in nodes if (nd[1] == -1) != (nd[2] == -1)]
            if one:
                nd = rng.choice(one)
                c = nd[1] if nd[1] != -1 else nd[2]
                nd[1] = c
                nd[2] = c
        rng.shuffle(nodes)
        return nodes

    def fmt(nodes):
        return str(len(nodes)) + '\n' + '\n'.join(' '.join(map(str, nd)) for nd in nodes)

    tests = [fmt([[5, -1, -1]]), fmt([[3, 3, -1]]), fmt([[1, 2, -1], [2, 1, -1]]), fmt([[1, 2, -1], [2, -1, -1]]),
             fmt([[1, 2, 2], [2, -1, -1]]), fmt([[1, 5, -1]]), fmt([[10, 20, 30], [20, -1, 40], [30, -1, -1], [40, -1, -1]]),
             fmt([[1, 2, 3], [2, -1, -1], [3, -1, 9]]), fmt([[1, 2, -1], [2, 3, -1], [3, 1, -1]]),
             fmt([[1, -1, -1], [2, -1, -1]]), fmt([[0, -1, 1], [1, -1, -1]])]
    kinds = ['valid', 'valid', 'extra', 'missing', 'drop', 'forest', 'cycle', 'dup']
    for n in (2, 3, 4, 5, 6, 8, 10):
        for kind in kinds:
            tests.append(fmt(make(n, kind, 2 * n + 2)))
    for kind in ('valid', 'extra', 'missing', 'drop', 'forest', 'cycle'):
        tests.append(fmt(make(3000, kind, 10 ** 9, 300)))
    N = 50000
    tests.append(fmt(make(N, 'valid', 10 ** 9, 2000)))
    tests.append(fmt(make(N, 'extra', 10 ** 9, 2000)))
    tests.append(fmt(make(N, 'missing', 10 ** 9, 1000)))
    tests.append(fmt(make(20000, 'forest', 10 ** 9, 1000)))
    return tests
